"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["75315"],{25603(e){e.exports=JSON.parse('{"id":"FIN-348","slug":"wholesale-banking","term":"Wholesale Banking","also_known_as":[],"difficulty":"Intermediate","definition":"Wholesale banking is the provision of banking services to large institutions, such as major corporations, governments, other banks and financial firms, rather than to individuals or small businesses.","explanation":["Wholesale banking deals in large transactions and specialised services. These can include large loans, often shared among several banks; cash management for companies operating in many countries; trade finance; foreign exchange; and access to financial markets.","The term also refers to banks borrowing and lending large sums among themselves, in what is called the wholesale funding market. Banks use this market to manage their day-to-day cash needs and to fund lending.","For example, a multinational company might use a bank\'s wholesale banking division to manage cash across twenty countries, arrange a 500 million loan and protect itself against currency movements.","Wholesale banking contrasts with retail banking, which serves individual consumers with everyday products such as current accounts and mortgages. Wholesale clients are generally considered more financially sophisticated, so wholesale banking is subject to different regulations and has less consumer protection than retail banking."],"note":"","total":1500,"prev":{"slug":"whole-life-insurance","term":"Whole Life Insurance"},"next":{"slug":"will","term":"Will"}}')}}]);